public class ApiKeyHandler : AuthorizationHandler<ApiKeyRequirement>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        ApiKeyRequirement requirement)
    {
        if (context.Resource is not HttpContext httpContext)
            return Task.CompletedTask;

        if (!httpContext.Request.Headers.TryGetValue("X-API-Key", out var key))
            return Task.CompletedTask;

        var hashedKey = Hash(key);
        if (_db.ApiKeys.Any(k => k.HashedKey == hashedKey && k.IsActive))
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("ApiKey", policy =>
        policy.Requirements.Add(new ApiKeyRequirement()));
});

builder.Services.AddScoped<IAuthorizationHandler, ApiKeyHandler>();

app.MapGet("/api/public", () => Results.Ok("Public"))
   .AllowAnonymous();

app.MapGet("/api/secure", () => Results.Ok("Secure"))
   .RequireAuthorization("ApiKey");
